// Title: Export Excel workbook to HTML without embedded CSS and attach an external stylesheet using Aspose.Cells for .NET
// Common Searches: Aspose.Cells export Excel to HTML without inline styles C# | Add external CSS link to HTML generated by Aspose.Cells .NET | Disable embedded CSS in Aspose.Cells HtmlSaveOptions | Insert <link> tag into Aspose.Cells HTML output programmatically | Customize HTML head section after saving workbook with Aspose.Cells | How to generate HTML that references a separate stylesheet using Aspose.Cells
// Tags: Aspose.Cells HtmlSaveOptions disable embedded CSS | external stylesheet linking for Aspose.Cells HTML export | modify generated HTML head tag C# | custom CSS for exported Excel HTML Aspose.Cells | programmatic insertion of link tag after HTML save | C# workbook to HTML with separate CSS file

using System;
using System.IO;
using Aspose.Cells;

// The example creates a workbook, fills it with data, saves it to HTML using Aspose.Cells (which embeds CSS by default), then reads the generated file, inserts a <link> element that points to an external stylesheet right after the <head> tag (or at the file start if <head> is missing), and writes the updated HTML back to disk, enabling custom styling without embedded CSS.
class HtmlExportWithExternalCss
{
    static void Main()
    {
        try
        {
            // Create a new workbook and add some sample data
            Workbook workbook = new Workbook();
            Worksheet sheet = workbook.Worksheets[0];
            sheet.Cells["A1"].PutValue("Name");
            sheet.Cells["B1"].PutValue("Score");
            sheet.Cells["A2"].PutValue("Alice");
            sheet.Cells["B2"].PutValue(85);
            sheet.Cells["A3"].PutValue("Bob");
            sheet.Cells["B3"].PutValue(92);

            // Configure HTML save options (default embeds CSS)
            HtmlSaveOptions htmlOptions = new HtmlSaveOptions();

            // Define the output HTML file path
            string htmlPath = "Report.html";

            // Export the workbook to HTML using the configured options
            workbook.Save(htmlPath, htmlOptions);

            // Ensure the HTML file was created before attempting to read it
            if (!File.Exists(htmlPath))
                throw new FileNotFoundException($"The HTML file '{htmlPath}' was not found after saving.");

            // Read the generated HTML content
            string htmlContent = File.ReadAllText(htmlPath);

            // Prepare the external stylesheet link tag
            string externalCssLink = "<link rel=\"stylesheet\" type=\"text/css\" href=\"styles.css\" />\n";

            // Find the position of the opening <head> tag (case‑insensitive)
            string headTag = "<head>";
            int headIndex = htmlContent.IndexOf(headTag, StringComparison.OrdinalIgnoreCase);
            if (headIndex != -1)
            {
                // Insert the link tag right after the <head> tag
                int insertPos = headIndex + headTag.Length;
                htmlContent = htmlContent.Insert(insertPos, "\n    " + externalCssLink);
            }
            else
            {
                // If <head> not found, prepend the link at the beginning of the file
                htmlContent = externalCssLink + htmlContent;
            }

            // Write the modified HTML back to the file
            File.WriteAllText(htmlPath, htmlContent);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
